const defaultHeroImages=[{"url":"assets/hero-ben.webp","alt":"Говорящий Бен","fit":"cover"},{"url":"assets/hero-shark.webp","alt":"Тралалеро Тралала","fit":"cover"},{"url":"assets/hero-gator.webp","alt":"Бомбардиро Крокодило","fit":"cover"},{"url":"assets/2022-001.webp","alt":"Хагги Вагги","fit":"contain"},{"url":"assets/2022-004.webp","alt":"Мудрое таинственное дерево","fit":"contain"},{"url":"assets/2024-005.webp","alt":"Мистер Фреш","fit":"contain"}];
async function loadAppearance(env){const row=await env.DB.prepare("SELECT * FROM settings WHERE key='appearance'").first();return {appearance:row?JSON.parse(row.data):{images:defaultHeroImages},revision:row?.revision||0};}
function validateHeroAppearance(input){if(!input||!Array.isArray(input.images)||input.images.length<4||input.images.length>24)throw Error('Выбери от 4 до 24 картинок: на главной будет случайная тройка.');const urls=new Set();return {images:input.images.map(image=>{if(!image||typeof image.url!=='string'||image.url.length>2048)throw Error('Проверь ссылку на картинку.');let url=image.url.trim();if(/^https:\/\//i.test(url)){let parsed;try{parsed=new URL(url);}catch{throw Error('Некорректная ссылка на картинку.');}if(parsed.username||parsed.password)throw Error('Ссылка не должна содержать логин или пароль.');url=parsed.href;}else if(!/^(assets\/[a-zA-Z0-9_.-]+|archive\/images\/[a-f0-9]+)\.(png|jpe?g|webp)$/i.test(url))throw Error('Нужна ссылка HTTPS, загруженный файл или картинка из библиотеки сайта.');if(urls.has(url))throw Error('Одна картинка выбрана несколько раз.');urls.add(url);if(typeof image.alt!=='string'||image.alt.length>160)throw Error('Название картинки — до 160 символов.');if(!['cover','contain'].includes(image.fit))throw Error('Выбери, как размещать картинку в рамке.');return {url,alt:image.alt.trim(),fit:image.fit};})};}
async function appearanceRoutes(req,env,p,isAdmin){if(p==='/api/appearance'&&req.method==='GET')return json(await loadAppearance(env));if(p!=='/api/admin/appearance')return null;if(!isAdmin)return error('Доступ только для администратора.',403);if(req.method==='GET')return json(await loadAppearance(env));if(req.method!=='PUT')return error('Метод не поддерживается.',405);const b=await body(req),old=await loadAppearance(env);if(b.revision!==old.revision)return error('Подборка уже изменена в другой вкладке. Обнови страницу.',409);let appearance;try{appearance=validateHeroAppearance(b.appearance);}catch(e){return error(e.message);}const result=await env.DB.prepare("INSERT INTO settings(key,data,revision) VALUES ('appearance',?,1) ON CONFLICT(key) DO UPDATE SET data=excluded.data,revision=settings.revision+1 WHERE settings.revision=?").bind(JSON.stringify(appearance),b.revision).run();if(!result.meta.changes)return error('Подборка уже изменена. Обнови страницу.',409);return json({appearance,revision:old.revision+1});}

const PLAYER_SESSION_MS=30*24*3600000;
const playerDigest=async text=>hex(await crypto.subtle.digest('SHA-256',encoder.encode(text)));
async function playerPassword(password,salt){const key=await crypto.subtle.importKey('raw',encoder.encode(password),'PBKDF2',false,['deriveBits']);return hex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:encoder.encode(salt),iterations:600000,hash:'SHA-256'},key,256));}
function playerNickname(value){if(typeof value!=='string')throw Error('Укажи ник.');const name=value.normalize('NFKC').trim();if(!/^[\p{L}\p{N}_.-]{3,24}$/u.test(name))throw Error('Ник: 3–24 буквы, цифры, точки, дефисы или подчёркивания, без пробелов.');return {name,key:name.toLocaleLowerCase('ru-RU').replaceAll('ё','е')};}
function checkPlayerPassword(password){if(typeof password!=='string'||password.length<8||password.length>128)throw Error('Пароль должен содержать от 8 до 128 символов.');}
async function playerLimit(req,env,kind,nickname='',limit=10){const now=Date.now(),ip=req.headers.get('cf-connecting-ip')||'unknown';for(const value of [kind+':ip:'+ip,...(nickname?[kind+':name:'+nickname]:[])]){const key='player:'+await playerDigest(value);await env.DB.prepare('INSERT INTO auth_rate (key,count,expires_at) VALUES (?,1,?) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN auth_rate.expires_at<? THEN 1 ELSE auth_rate.count+1 END,expires_at=CASE WHEN auth_rate.expires_at<? THEN excluded.expires_at ELSE auth_rate.expires_at END').bind(key,now+900000,now,now).run();const rate=await env.DB.prepare('SELECT count FROM auth_rate WHERE key=?').bind(key).first();const threshold=value.startsWith(kind+':ip:')?(kind==='register'?30:60):limit;if(rate.count>threshold)return error('Слишком много попыток. Подожди 15 минут.',429);}return null;}
function publicAccount(row){return row?{id:row.id,nickname:row.nickname}:null;}
async function playerAccount(req,env){const token=req.headers.get('x-account-token');if(!/^[a-f0-9]{64}$/.test(token||''))return null;return await env.DB.prepare('SELECT a.id,a.nickname FROM accounts a JOIN player_sessions s ON s.account_id=a.id AND s.auth_version=a.auth_version WHERE s.token_hash=? AND s.expires_at>?').bind(await playerDigest(token),Date.now()).first();}
async function playerSession(env,account){const token=crypto.randomUUID().replaceAll('-','')+crypto.randomUUID().replaceAll('-','');await env.DB.prepare('INSERT INTO player_sessions(token_hash,account_id,auth_version,created_at,expires_at) VALUES (?,?,?,?,?)').bind(await playerDigest(token),account.id,account.auth_version,Date.now(),Date.now()+PLAYER_SESSION_MS).run();return token;}
async function playerRoutes(req,env,p){
 if(!p.startsWith('/api/account/'))return null;
 if(p==='/api/account/me'&&req.method==='GET'){const account=await playerAccount(req,env);if(account)await env.DB.prepare('UPDATE player_sessions SET expires_at=? WHERE token_hash=? AND expires_at<?').bind(Date.now()+PLAYER_SESSION_MS,await playerDigest(req.headers.get('x-account-token')),Date.now()+PLAYER_SESSION_MS-86400000).run();return json({account:publicAccount(account)});}
 if(req.method!=='POST')return error('Метод не поддерживается.',405);
 if(p==='/api/account/logout'){const token=req.headers.get('x-account-token');if(token)await env.DB.prepare('DELETE FROM player_sessions WHERE token_hash=?').bind(await playerDigest(token)).run();return json({ok:true});}
 if(!['/api/account/register','/api/account/login','/api/account/recover'].includes(p))return error('Не найдено.',404);
 const b=await body(req);let nick;try{nick=playerNickname(b.nickname);checkPlayerPassword(b.password);}catch(e){return error(e.message);}
 const rate=await playerLimit(req,env,p.split('/').pop(),nick.key,p.endsWith('register')?5:10);if(rate)return rate;
 if(p==='/api/account/register'){
  if(b.consent!==true)return error('Подтверди создание аккаунта и сохранение ника.');
  const existing=await env.DB.prepare('SELECT id FROM accounts WHERE nickname_key=?').bind(nick.key).first();if(existing)return error('Этот ник уже занят. Войди в свой аккаунт или выбери другой.',409);
  const account={id:crypto.randomUUID(),nickname:nick.name,auth_version:1},salt=crypto.randomUUID(),recoveryCode=crypto.randomUUID().replaceAll('-','');
  const inserted=await env.DB.prepare('INSERT INTO accounts(id,nickname,nickname_key,password_hash,password_salt,recovery_hash,created_at) VALUES (?,?,?,?,?,?,?) ON CONFLICT(nickname_key) DO NOTHING').bind(account.id,nick.name,nick.key,await playerPassword(b.password,salt),salt,await playerDigest(recoveryCode),Date.now()).run();if(!inserted.meta.changes)return error('Этот ник уже занят.',409);
  return json({account:publicAccount(account),token:await playerSession(env,account),recoveryCode},201);
 }
 const account=await env.DB.prepare('SELECT * FROM accounts WHERE nickname_key=?').bind(nick.key).first();
 if(p==='/api/account/recover'){
  const code=typeof b.recoveryCode==='string'?b.recoveryCode.toLowerCase().replace(/[\s-]/g,''):'';
  if(!/^[a-f0-9]{32}$/.test(code)||!account||!equal(account.recovery_hash,await playerDigest(code)))return error('Неверный ник или код восстановления.',401);
  const salt=crypto.randomUUID(),recoveryCode=crypto.randomUUID().replaceAll('-','');const updated=await env.DB.prepare('UPDATE accounts SET password_hash=?,password_salt=?,recovery_hash=?,auth_version=auth_version+1 WHERE id=? AND auth_version=?').bind(await playerPassword(b.password,salt),salt,await playerDigest(recoveryCode),account.id,account.auth_version).run();if(!updated.meta.changes)return error('Данные уже изменились. Повтори восстановление.',409);
  account.auth_version++;return json({account:publicAccount(account),token:await playerSession(env,account),recoveryCode});
 }
 const valid=equal(account?.password_hash||'0'.repeat(64),await playerPassword(b.password,account?.password_salt||'missing-account'));
 if(!account||!valid)return error('Неверный ник или пароль.',401);
 return json({account:publicAccount(account),token:await playerSession(env,account)});
}
async function prepareRanking(env,modeId,questions){const m=(await loadModes(env)).modes.find(m=>m.id===modeId&&m.enabled);if(!m)return null;const pool=modePool(m,questions);return {mode:m,key:await playerDigest(JSON.stringify({id:m.id,count:m.count,selection:m.selection,pool:pool.map(q=>[q.id,q.revision||0,q.level]).sort((a,b)=>a[0].localeCompare(b[0]))}))};}
async function publicBoard(req,env){const url=new URL(req.url),modes=(await loadModes(env)).modes.filter(m=>m.enabled);const modeId=url.searchParams.get('mode')||modes[0]?.id;const ranking=await prepareRanking(env,modeId,await loadQuestions(env));
 const stats=await env.DB.prepare('SELECT COUNT(*) AS attempts,COUNT(DISTINCT account_id) AS players,ROUND(AVG(percent),1) AS average FROM attempts WHERE finished_at IS NOT NULL AND deleted_at IS NULL').first();
 if(!ranking)return json({modes,items:[],stats,modeId:null});
 const rows=await env.DB.prepare(`SELECT nickname,percent,points,max_points,correct,total,duration,finished_at FROM (SELECT a.nickname,t.percent,t.points,t.max_points,t.correct,t.total,t.finished_at,t.finished_at-t.started_at AS duration,ROW_NUMBER() OVER (PARTITION BY t.account_id ORDER BY t.percent DESC,t.points DESC,(t.finished_at-t.started_at) ASC,t.finished_at ASC,t.id ASC) AS board_position FROM attempts t JOIN accounts a ON a.id=t.account_id WHERE t.board_key=? AND t.public_consent=1 AND t.finished_at IS NOT NULL AND t.deleted_at IS NULL) ranked WHERE board_position=1 ORDER BY percent DESC,points DESC,duration ASC,finished_at ASC,nickname ASC LIMIT 100`).bind(ranking.key).all();
 return json({modes,modeId,items:rows.results,stats,version:ranking.key.slice(0,10)});
}

const defaultModes=[
{id:'quick',name:'Быстрый скролл',description:'Проверить, в теме ли ты.',count:18,selection:'all',questionIds:[],enabled:true},
{id:'big',name:'Большой заход',description:'От базы до забытых мемов.',count:36,selection:'all',questionIds:[],enabled:true},
{id:'full',name:'Бездна рекомендаций',description:'Весь архив. Без сокращений.',count:0,selection:'all',questionIds:[],enabled:true}];
function modePool(mode,questions,years=[2021,2022,2023,2024,2025,2026]){return mode?questions.filter(q=>q.enabled!==false&&years.includes(q.year)&&(mode.selection==='all'||mode.questionIds.includes(q.id))):[];}
function modeCount(mode,pool){return mode?Math.min(mode.count||pool.length,pool.length):0;}
function validateModes(modes,questions){if(!Array.isArray(modes)||!modes.length||modes.length>30)throw Error('Допустимо от 1 до 30 режимов.');const ids=new Set(),qids=new Set(questions.map(q=>q.id));return modes.map(m=>{if(!m||typeof m!=='object'||!/^[a-zA-Z0-9_-]{1,80}$/.test(m.id)||ids.has(m.id))throw Error('Неверный или повторяющийся ID режима.');ids.add(m.id);if(typeof m.name!=='string'||!m.name.trim()||m.name.length>100||typeof m.description!=='string'||m.description.length>600)throw Error('Название — до 100 символов; описание — до 600.');if(!Number.isInteger(m.count)||m.count<0||m.count>1000||!['all','manual'].includes(m.selection))throw Error('Проверь число вопросов и состав режима.');if(!Array.isArray(m.questionIds)||new Set(m.questionIds).size!==m.questionIds.length||m.questionIds.some(id=>!qids.has(id)))throw Error('В составе режима есть неизвестные вопросы.');return {id:m.id,name:m.name.trim(),description:m.description.trim(),count:m.count,selection:m.selection,questionIds:m.questionIds,enabled:m.enabled!==false};});}

async function loadModes(env){const row=await env.DB.prepare("SELECT * FROM settings WHERE key='modes'").first();return {modes:row?JSON.parse(row.data):defaultModes,revision:row?.revision||0};}
async function modeRoutes(req,env,p,isAdmin){
 if(p==='/api/archive'&&req.method==='GET')return json({schemaVersion:1,questions:await loadQuestions(env),modes:(await loadModes(env)).modes.filter(m=>m.enabled),appearance:(await loadAppearance(env)).appearance});
 if(p==='/api/modes'&&req.method==='GET'){const data=await loadModes(env);return json({...data,modes:data.modes.filter(m=>m.enabled)});}
 if(p!=='/api/admin/modes')return null;if(!isAdmin)return error('Доступ только для администратора.',403);
 if(req.method==='GET')return json(await loadModes(env));if(req.method!=='PUT')return error('Метод не поддерживается.',405);
 const b=await body(req),old=await loadModes(env);if(b.revision!==old.revision)return error('Режимы уже изменены в другой вкладке. Обнови страницу.',409);let modes;try{modes=validateModes(b.modes,await loadQuestions(env,true));}catch(e){return error(e.message);}
 const r=await env.DB.prepare("INSERT INTO settings(key,data,revision) VALUES ('modes',?,1) ON CONFLICT(key) DO UPDATE SET data=excluded.data,revision=settings.revision+1 WHERE settings.revision=?").bind(JSON.stringify(modes),b.revision).run();if(!r.meta.changes)return error('Режимы изменены. Обнови страницу.',409);return json({modes,revision:old.revision+1});
}



function normalizeAnswer(value){return typeof value==='string'?value.normalize('NFKC').toLocaleLowerCase('ru-RU').replaceAll('ё','е').replace(/[^\p{L}\p{N}]+/gu,' ').trim():'';}
function isCorrect(q,value){if(typeof value!=='string')return false;if(q.options.length)return value===q.answer;const normalized=normalizeAnswer(value);return !!normalized&&[q.answer,...(q.acceptedAnswers||[])].some(a=>normalizeAnswer(a)===normalized);}
function validAnswer(q,value){return value===null||(typeof value==='string'&&(q.options.length?q.options.includes(value):value.length<=300&&!!normalizeAnswer(value)));}


async function loadQuestions(env,all=false){const rows=await env.DB.prepare('SELECT * FROM questions ORDER BY updated_at,id').all();const map=new Map(bank.map(q=>[q.id,{...q,enabled:true,revision:0}]));for(const r of rows.results)map.set(r.id,{...JSON.parse(r.data),id:r.id,enabled:!!r.enabled,revision:r.revision});return [...map.values()].filter(q=>all||q.enabled);}
function validateQuestion(input,id){if(!input||typeof input!=='object')throw Error('Неверные данные вопроса.');const text=(key,max,required=false)=>{const v=typeof input[key]==='string'?input[key].trim():'';if(v.length>max||(required&&!v))throw Error('Заполни поле «'+({prompt:'Вопрос',topic:'Название мема',explanation:'Объяснение'}[key]||key)+'» (до '+max+' символов).');return v;};
 const options=Array.isArray(input.options)?input.options.map(v=>typeof v==='string'?v.trim():''):null;if(!options||options.length>10||options.some(v=>!v||v.length>300)||new Set(options).size!==options.length)throw Error('Добавь от 1 до 10 разных вариантов или выбери письменный ответ.');const answer=typeof input.answer==='string'?input.answer.trim():'';if(!answer||answer.length>300||(options.length&&!options.includes(answer)))throw Error('Укажи правильный ответ (до 300 символов).');let acceptedAnswers=[];if(!options.length){if(!normalizeAnswer(answer))throw Error('Ответ должен содержать буквы или цифры.');const aliases=input.acceptedAnswers||[];if(!Array.isArray(aliases)||aliases.length>20||aliases.some(a=>typeof a!=='string'||a.length>300||!normalizeAnswer(a)))throw Error('Допустимо до 20 дополнительных написаний ответа, каждое до 300 символов.');acceptedAnswers=[...new Set(aliases.map(a=>a.trim()))];}if(!Number.isInteger(input.year)||input.year<2021||input.year>2026)throw Error('Год должен быть от 2021 до 2026.');if(![1,2,3].includes(input.level))throw Error('Выбери сложность.');
 const urls=(key)=>{const a=input[key]||[];if(!Array.isArray(a)||a.length>8||a.some(u=>typeof u!=='string'||u.length>2048||!/^https?:\/\/[^\s]+$/i.test(u)))throw Error('Проверь ссылки: нужны адреса http или https (до 8).');return a;};const image=text('image',2048);if(image&&!/^https?:\/\/[^\s]+$/i.test(image)&&!/^assets\/[a-zA-Z0-9_.-]+$/.test(image))throw Error('Укажи прямую ссылку http/https на изображение или загрузи файл.');
 const credit=text('imageCredit',2048);if(credit&&!/^https?:\/\/[^\s]+$/i.test(credit))throw Error('Источник картинки должен быть ссылкой http или https.');
 return {id,topic:text('topic',160,true),prompt:text('prompt',1200,true),year:input.year,level:input.level,kind:text('kind',80)||'Знаток',options,answer,acceptedAnswers,explanation:text('explanation',4000,true),quote:text('quote',600),image:image||null,imageCredit:credit||null,sources:urls('sources'),media:urls('media')};}
async function boundedBytes(req,limit){const reader=req.body?.getReader();if(!reader)return null;const chunks=[];let size=0;for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>limit){await reader.cancel();return null;}chunks.push(value);}const bytes=new Uint8Array(size);let offset=0;for(const c of chunks){bytes.set(c,offset);offset+=c.length;}return bytes;}
async function cmsRoutes(req,env,p,isAdmin){
 if(p==='/api/questions'&&req.method==='GET')return json({questions:await loadQuestions(env),modes:(await loadModes(env)).modes.filter(m=>m.enabled),appearance:(await loadAppearance(env)).appearance});
 const media=/^\/api\/images\/([a-f0-9-]{36}\.(?:png|jpg|webp))$/.exec(p);if(media&&req.method==='GET'){if(!env.BUCKET)return error('Хранилище изображений недоступно.',503);const object=await env.BUCKET.get('quiz/'+media[1]);if(!object)return error('Изображение не найдено.',404);return new Response(object.body,{headers:{'Content-Type':object.httpMetadata?.contentType||'application/octet-stream','X-Content-Type-Options':'nosniff','Cache-Control':'public, max-age=31536000, immutable'}});}
 if(!p.startsWith('/api/admin/questions')&&p!=='/api/admin/images')return null;
 if(!isAdmin)return error('Доступ только для администратора.',403);
 if(req.method!=='GET'&&!validOrigin(req,env))return error('Редактор доступен только из админки.',403);
 if(p==='/api/admin/images'&&req.method==='POST'){
  if(!env.BUCKET)return error('Хранилище изображений недоступно.',503);const bytes=await boundedBytes(req,2*1024*1024);if(!bytes||bytes.length<12)return error('Нужен файл PNG, JPG или WebP размером до 2 МБ.');let type,extension;if(bytes[0]===255&&bytes[1]===216&&bytes[2]===255){type='image/jpeg';extension='jpg';}else if([137,80,78,71,13,10,26,10].every((v,i)=>bytes[i]===v)){type='image/png';extension='png';}else if(String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP'){type='image/webp';extension='webp';}else return error('Формат не поддерживается. Выбери PNG, JPG или WebP.');
  const filename=crypto.randomUUID()+'.'+extension;await env.BUCKET.put('quiz/'+filename,bytes,{httpMetadata:{contentType:type}});return json({url:env.BUCKET.publicUrl?env.BUCKET.publicUrl('quiz/'+filename):new URL('/api/images/'+filename,req.url).href},201);
 }
 if(p==='/api/admin/questions'&&req.method==='GET')return json({questions:await loadQuestions(env,true)});
 const match=/^\/api\/admin\/questions\/([a-zA-Z0-9_-]{1,80})$/.exec(p);const creating=p==='/api/admin/questions'&&req.method==='POST';
 if(!creating&&!(match&&req.method==='PUT'))return error('Метод не поддерживается.',405);
 const b=await body(req),id=creating?'custom-'+crypto.randomUUID():match[1];const questions=await loadQuestions(env,true),existing=questions.find(q=>q.id===id);if(!creating&&!existing)return error('Вопрос не найден.',404);if(creating&&questions.length>=1000)return error('Достигнут лимит в 1000 вопросов.');const expected=existing?.revision||0;if(!creating&&b.revision!==expected)return error('Этот вопрос уже изменён. Вернись в список и открой его заново.',409);
 let q;try{q=validateQuestion(b,id);}catch(e){return error(e.message);}const enabled=b.enabled!==false;
 const result=await env.DB.prepare('INSERT INTO questions (id,data,enabled,revision,updated_at) VALUES (?,?,?,1,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data,enabled=excluded.enabled,revision=questions.revision+1,updated_at=excluded.updated_at WHERE questions.revision=?').bind(id,JSON.stringify(q),enabled?1:0,Date.now(),expected).run();if(!result.meta.changes)return error('Вопрос уже изменён. Открой его заново.',409);return json({...q,enabled,revision:expected+1},creating?201:200);
}


